import { defaultPayloadConverter } from '@temporalio/common';
import { temporal } from '@temporalio/proto';

// Synthetic Temporal service events, not SDK calls or a trace generated by the
// code under test. All runs terminate. Each event references real event IDs.
const payload = (value: unknown) => defaultPayloadConverter.toPayload(value);
const payloads = (...values: unknown[]) => ({ payloads: values.map(payload) });
const queue = { name: 'high' };
const identity = 'offline-replay';
const second = (seconds: number) => ({ seconds });
export const epoch = Date.UTC(2026, 0, 1);
export const supportRun = '11111111-1111-4111-8111-111111111111';
export const senderRun = '22222222-2222-4222-8222-222222222222';
export const timedOut = Symbol('start-to-close timeout');
export const rejected = Symbol('terminal rejection');
export const rejectedFailure = { message: 'Provider rejected the request', applicationFailureInfo: { type: 'CHANNEL_REQUEST_REJECTED', nonRetryable: true } };
export const maxAttemptsReached = 'RETRY_STATE_MAXIMUM_ATTEMPTS_REACHED';
export const timeoutFailure = { message: 'activity StartToClose timeout', timeoutFailureInfo: { timeoutType: 'TIMEOUT_TYPE_START_TO_CLOSE' } };

export class History {
  private events: Record<string, unknown>[] = [];
  private taskId = 0;
  private activityId = 0;
  private patches: string[] = [];
  constructor(workflowType: string, runId: string, args: unknown[], parent: { workflowId: string; runId: string; initiatedId: number },
    private now = epoch) {
    this.event('WorkflowExecutionStarted', { workflowType: { name: workflowType }, taskQueue: queue, input: payloads(...args),
      parentWorkflowNamespace: 'default', parentWorkflowExecution: { workflowId: parent.workflowId, runId: parent.runId },
      parentInitiatedEventId: parent.initiatedId, workflowTaskTimeout: second(10),
      originalExecutionRunId: runId, firstExecutionRunId: runId, attempt: 1 });
    this.task();
  }

  private event(type: string, attrs: Record<string, unknown>) {
    const eventId = this.events.length + 1;
    const eventType = `EVENT_TYPE_${type.replace(/([a-z])([A-Z])/g, '$1_$2').toUpperCase()}`;
    this.events.push({ eventId, eventType, eventTime: { seconds: Math.floor(this.now / 1000), nanos: (this.now % 1000) * 1e6 },
      [`${type[0].toLowerCase()}${type.slice(1)}EventAttributes`]: attrs });
    return eventId;
  }

  private command(type: string, attrs: Record<string, unknown>) {
    return this.event(type, { workflowTaskCompletedEventId: this.taskId, ...attrs });
  }

  private task() {
    const scheduledEventId = this.event('WorkflowTaskScheduled', { taskQueue: queue, startToCloseTimeout: second(10), attempt: 1 });
    const startedEventId = this.event('WorkflowTaskStarted', { scheduledEventId, identity, requestId: `task-${scheduledEventId}` });
    this.taskId = this.event('WorkflowTaskCompleted', { scheduledEventId, startedEventId, identity,
      // Core checks activity and child IDs/types and emits version search attributes;
      // the JS SDK cancels the guidance deadline when guidance completes.
      ...(this.taskId === 0 ? { sdkMetadata: { coreUsedFlags: [1, 2, 3], langUsedFlags: [1, 2] } } : {}) });
  }

  upsert(fields: Record<string, string[]>) {
    const indexedFields = Object.fromEntries(Object.entries(fields).map(([key, value]) => [key, payload(value)]));
    this.command('UpsertWorkflowSearchAttributes', { searchAttributes: { indexedFields } });
  }

  patch(id: string) {
    this.command('MarkerRecorded', { markerName: 'core_patch', details: { 'patch-data': payloads({ id, deprecated: false }) } });
    this.patches.push(id);
    this.upsert({ TemporalChangeVersion: [...this.patches].sort() });
  }

  timer(seconds: number) { return this.command('TimerStarted', { timerId: '1', startToFireTimeout: second(seconds) }); }
  cancelTimer(startedEventId: number) { this.command('TimerCanceled', { timerId: '1', startedEventId, identity }); }

  activity(name: string, args: unknown[], result: unknown, seconds: number, attempts: number, elapsedMs: number, rejection = rejectedFailure) {
    const scheduledEventId = this.command('ActivityTaskScheduled', { activityId: String(++this.activityId), activityType: { name },
      taskQueue: queue, input: payloads(...args), startToCloseTimeout: second(seconds), retryPolicy: {
        initialInterval: second(attempts === 4 ? 5 : attempts === 3 ? 2 : 1), backoffCoefficient: 2,
        maximumInterval: second(attempts === 4 ? 60 : attempts === 3 ? 30 : 100), maximumAttempts: attempts } });
    const startedEventId = this.event('ActivityTaskStarted', { scheduledEventId, identity, attempt: 1, requestId: `activity-${scheduledEventId}` });
    this.now += result === timedOut ? seconds * 1_000 : elapsedMs;
    if (result === timedOut) this.event('ActivityTaskTimedOut', { scheduledEventId, startedEventId,
      failure: timeoutFailure, retryState: maxAttemptsReached });
    else if (result === rejected) this.event('ActivityTaskFailed', { scheduledEventId, startedEventId, identity,
      failure: rejection, retryState: 'RETRY_STATE_NON_RETRYABLE_FAILURE' });
    else this.event('ActivityTaskCompleted', { scheduledEventId, startedEventId, identity, result: payloads(result) });
    this.task();
    return { scheduledEventId, startedEventId };
  }

  child(id: string, input: unknown, terminal: { result: unknown } | { failure: unknown }, elapsedMs: number) {
    const workflowType = { name: 'sendChannelMessageFromAgentWorkflow' };
    const workflowExecution = { workflowId: id, runId: senderRun };
    const initiatedEventId = this.command('StartChildWorkflowExecutionInitiated', { namespace: 'default', workflowId: id, workflowType,
      taskQueue: queue, parentClosePolicy: 'PARENT_CLOSE_POLICY_REQUEST_CANCEL', workflowIdReusePolicy: 'WORKFLOW_ID_REUSE_POLICY_ALLOW_DUPLICATE',
      input: payloads(input) });
    const startedEventId = this.event('ChildWorkflowExecutionStarted', { namespace: 'default', initiatedEventId, workflowType, workflowExecution });
    this.task();
    const ids = { namespace: 'default', initiatedEventId, startedEventId, workflowType, workflowExecution };
    this.now += elapsedMs;
    if ('failure' in terminal) this.event('ChildWorkflowExecutionFailed', { ...ids, failure: terminal.failure, retryState: 'RETRY_STATE_RETRY_POLICY_NOT_SET' });
    else this.event('ChildWorkflowExecutionCompleted', { ...ids, result: payloads(terminal.result) });
    this.task();
    return initiatedEventId;
  }

  close(terminal: { result: unknown } | { failure: unknown }) {
    if ('failure' in terminal) this.command('WorkflowExecutionFailed', { failure: terminal.failure, retryState: 'RETRY_STATE_RETRY_POLICY_NOT_SET' });
    else this.command('WorkflowExecutionCompleted', { result: payloads(terminal.result) });
    return temporal.api.history.v1.History.fromObject({ events: this.events });
  }
}
